	private static readonly string SAVE_STATE_LEGACY_TYPE = "SaveState";
	private static readonly string GPROPERTIES_TAG = "GPROPERTIES";
	private static readonly string PROPERTIES_NAME = "GPROPERTIES_NAME";
	private static readonly string LEGACY_PROPERTIES_NAME = "SAVE_STATE_NAME";
	protected static readonly string STATE = "STATE";

	/** The xml attribute for the type of the property (e.g., int, String, etc)*/
	protected static readonly string ATTRIBUTE_TYPE = "TYPE";

	/** The xml attribute for the 'key' in the key/value mapping */
