	/**
	 * Construct a new GProperties object using the given XML element.
	 * @param root XML contents of GProperties
	 */
	public GProperties(Element root) : this(root.getName())
    {
		foreach (Element elem in root.getChildren()) {
			processElement(elem);
		}
	}

	/**
	 * Construct a new GProperties object using the given JSonObject.
	 * @param root JSonObject representing a GProperties
	 */
	public GProperties(JsonObject root) : this(getPropertiesName(root))
    {
		JsonObject values = root.get("VALUES").getAsJsonObject();
		JsonObject types = root.get("TYPES").getAsJsonObject();
		JsonObject enumClasses = root.get("ENUM_CLASSES").getAsJsonObject();

		foreach (string name in values.keySet()) {
			string type = types.get(name).getAsString();
			JsonElement valueElement = values.get(name);
			JsonElement enumClass = enumClasses.get(name);
			object value = getObjectFromJson(type, valueElement, enumClass);
			if (value != null) {
				map.put(name, value);
			}
		}
	}

