			catch (Exception e) {
				Msg.warn(this, "Error processing primitive value in GProperties", e);
			}
		}
		else if (tag.equals("ARRAY")) {
			if (type == null) {
				return;
			}

			try {
				List<object> list = elem.getChildren(ARRAY_ELEMENT_NAME);
				Iterator<object> it = list.iterator();
				int i = 0;
				if (type.equals("short")) {
					short[] vals = new short[list.size()];
					while (it.hasNext()) {
						Element e = (Element) it.next();
						vals[i++] = Short.parseShort(e.getAttributeValue(ATTRIBUTE_VALUE));
					}
					map.put(name, vals);
				}
				else if (type.equals("int")) {
					int[] vals = new int[list.size()];
					while (it.hasNext()) {
						Element e = (Element) it.next();
						vals[i++] = Integer.parseInt(e.getAttributeValue(ATTRIBUTE_VALUE));
					}
					map.put(name, vals);
				}
				else if (type.equals("long")) {
					long[] vals = new long[list.size()];
					while (it.hasNext()) {
						Element e = (Element) it.next();
						vals[i++] = Long.parseLong(e.getAttributeValue(ATTRIBUTE_VALUE));
					}
					map.put(name, vals);
				}
				else if (type.equals("float")) {
					float[] vals = new float[list.size()];
					while (it.hasNext()) {
						Element e = (Element) it.next();
						vals[i++] = Float.parseFloat(e.getAttributeValue(ATTRIBUTE_VALUE));
					}
					map.put(name, vals);
				}
				else if (type.equals("double")) {
					double[] vals = new double[list.size()];
					while (it.hasNext()) {
						Element e = (Element) it.next();
						vals[i++] = Double.parseDouble(e.getAttributeValue(ATTRIBUTE_VALUE));
					}
					map.put(name, vals);
				}
				else if (type.equals("boolean")) {
					bool[] vals = new bool[list.size()];
					while (it.hasNext()) {
						Element e = (Element) it.next();
						vals[i++] =
							Boolean.valueOf(e.getAttributeValue(ATTRIBUTE_VALUE)).booleanValue();
					}
					map.put(name, vals);
				}
				else if (type.equals("string")) {
					string[] vals = new string[list.size()];
					while (it.hasNext()) {
						Element e = (Element) it.next();
						vals[i++] = e.getAttributeValue(ATTRIBUTE_VALUE);
					}
					map.put(name, vals);
				}
			}
			catch (Exception exc) {
				Msg.warn(this, "Error processing array value in GProperties", exc);
			}
		}
		else if (tag.equals("ENUM")) {
			if (type == null) {
				return;
			}
			if (type.equals("stringenum")) {
				return;
			}
			if (type.equals("enum")) {
				string className = elem.getAttributeValue("CLASS");
				Enum<object> e = getEnumValue(className, value);
				if (e != null) {
					map.put(name, e);
				}
