		}
		else if (tag.equals(GPROPERTIES_TAG)) {
			Element element = elem.getChildren().get(0);
			if (element != null) {
				map.put(name, new GProperties(element));
			}
		}
		else if (tag.equals("NULL")) {
			map.put(name, null);
