	private static string getPropertiesName(JsonObject root) {
		if (root.has(LEGACY_PROPERTIES_NAME)) {
			return root.get(LEGACY_PROPERTIES_NAME).getAsString();
		}
		return root.get(PROPERTIES_NAME).getAsString();
	}

	private object getObjectFromJson(string type, JsonElement value, JsonElement enumClass) {

		switch (type) {
			case "null":
				return null;
			case "String":
				return value.getAsString();
			case "Color":
				return new Color(value.getAsInt());
			case "Date":
				return parseDate(value.getAsString());
			case "File":
				return new File(value.getAsString());
			case "KeyStroke":
				return KeyStroke.getKeyStroke(value.getAsString());
			case "Font":
				return Font.decode(value.getAsString());
			case "byte":
				return value.getAsByte();
			case "short":
				return value.getAsShort();
			case "int":
				return value.getAsInt();
			case "long":
				return value.getAsLong();
			case "float":
				return value.getAsFloat();
			case "double":
				return value.getAsDouble();
			case "boolean":
				return value.getAsBoolean();
			case "byte[]":
				JsonArray byteArray = value.getAsJsonArray();
				byte[] bytes = new byte[byteArray.size()];
				for (int i = 0; i < bytes.length; i++) {
					bytes[i] = byteArray.get(i).getAsByte();
				}
				return bytes;
			case "short[]":
				JsonArray shortArray = value.getAsJsonArray();
				short[] shorts = new short[shortArray.size()];
				for (int i = 0; i < shorts.length; i++) {
					shorts[i] = shortArray.get(i).getAsShort();
				}
				return shorts;
			case "int[]":
				JsonArray intArray = value.getAsJsonArray();
				int[] ints = new int[intArray.size()];
				for (int i = 0; i < ints.length; i++) {
					ints[i] = intArray.get(i).getAsInt();
				}
				return ints;
			case "long[]":
				JsonArray longArray = value.getAsJsonArray();
				long[] longs = new long[longArray.size()];
				for (int i = 0; i < longs.length; i++) {
					longs[i] = longArray.get(i).getAsLong();
				}
				return longs;
			case "float[]":
				JsonArray floatArray = value.getAsJsonArray();
				float[] floats = new float[floatArray.size()];
				for (int i = 0; i < floats.length; i++) {
					floats[i] = floatArray.get(i).getAsFloat();
				}
				return floats;
			case "double[]":
				JsonArray doubleArray = value.getAsJsonArray();
				double[] doubles = new double[doubleArray.size()];
				for (int i = 0; i < doubles.length; i++) {
					doubles[i] = doubleArray.get(i).getAsDouble();
				}
				return doubles;
			case "boolean[]":
				JsonArray boolArray = value.getAsJsonArray();
				bool[] booleans = new bool[boolArray.size()];
				for (int i = 0; i < booleans.length; i++) {
					booleans[i] = boolArray.get(i).getAsBoolean();
				}
				return booleans;
			case "String[]":
				JsonArray stringArray = value.getAsJsonArray();
				string[] strings = new string[stringArray.size()];
				for (int i = 0; i < strings.length; i++) {
					strings[i] = stringArray.get(i).getAsString();
				}
				return strings;
			case "xml":
				try {
					return XmlUtilities.fromString(value.getAsString());
				}
				catch (Exception e) when (e is JDOMException or IOException) {
					throw new AssertException("Error processing embedded XML");
				}

			case "enum":
				string enumClassName = enumClass.getAsString();
				string enumValue = value.getAsString();
				return getEnumValue(enumClassName, enumValue);

			case G_PROPERTIES_TYPE:
			case SAVE_STATE_LEGACY_TYPE:
				JsonObject json = (JsonObject) value;
				return new GProperties(json);

			default:
				throw new AssertException("Unknown type: " + type);
		}
	}

	private Date parseDate(string dateString) {
		try {
			return DATE_FORMAT.parse(dateString);
		}
		catch (ParseException e) {
			throw new AssertException("Can't parse date string: " + dateString);
		}
	}

	Enum<object> getEnumValue(string enumClassName, string value) {
		try {
			// It would be better to restrict this to some interface we define. Otherwise, we ought
			// to examine the static initializers of every enum in our classpath. Luckily, the
			// constructor invocations are all defined by the enum values, and so cannot be randomly
			// invoked. Famous last words: I doubt there's anything of concern in any enum's static
			// initializer....
			Class<object> enumClass =
				ClassSearcher.forNameSafe(enumClassName, typeof(Enum), getClass().getClassLoader());

			Method m = enumClass.getMethod("valueOf", new Class[] { typeof(string) });
			if (m != null) {
				return (Enum<object>) m.invoke(null, new object[] { value });
			}
		}
		catch (Exception e) {
			// This implies we have a saved enum value that no longer exists or we are in a branch
			// that does not have the enum class that has been saved.  Just emit a debug message to 
			// help the developer in the case that there may be a real issue.
			Msg.debug(this, "Can't find field " + value + " in enum class " + enumClassName);
		}
		return null;
	}

	/**
	 * Outputs this GProperties to a file using Json
	 * <P>
	 * For example, a GProperties that is created with:
	 * <pre>
	 *  ss = new GProperties("foo")
	 *	ss.putString("Name", "Bob");
	 *	ss.putBoolean("Retired", true);
	 *	ss.putInt("Age", 65);
	 *	ss.putEnum("Endian", Endian.BIG);
	 *
	 *  would produce a Json file with the following text
	 *
	 * {
	 *  "GPROPERTIES NAME": "foo",
	 *  "VALUES": {
	 *    "Name": "Bob"
	 *    "Retired": true,
	 *    "Age": 65,
	 *    "Endian": "BIG",
	 *  },
	 *  "TYPES": {
	 *    "Name": "String"
	 *    "Retired": "boolean",
	 *    "Age": "int",
	 *    "Endian": "enum",
	 *  },	
	 *  "ENUM CLASSES": {
	 *    "Endian": "ghidra.program.model.lang.Endian"
	 *  }
	 *}
	 * </pre>
	 * 
	 * @param file the file to save to
	 * @throws IOException if an error occurs writing to the given file
	 */
	public void saveToJsonFile(File file)
    {
		Gson gson = new GsonBuilder().setPrettyPrinting().create();
		JsonObject saveToJson = saveToJson();
		using (FileWriter writer = new FileWriter(file))
{
			writer.write(gson.toJson(saveToJson));
		}
	}

	/**
	 * Write the properties to a file as XML
	 * @param file the file to write to.
	 * @throws IOException if the file could not be written
	 */
	public void saveToXmlFile(File file)
    {
		Element saveToXml = saveToXml();
		byte[] bytes = XmlUtilities.xmlToByteArray(saveToXml);
		FileUtilities.writeBytes(file, bytes);
	}

	/**
	 * Save this object to an XML element.
	 * @return Element XML element containing the properties
	 */
	public Element saveToXml() {
		Element root = new Element(propertiesName);
		foreach (string key in map.keySet()) {
			object value = map.get(key);
			Element elem = createElement(key, value);
			root.addContent(elem);
		}
		return root;
	}

	/**
	 * Called to save this class' properties to xml.
	 * 
	 * @param propertyName the property name to save
	 * @param value the property value
	 * @return the xml element
	 */
	protected Element createElement(string propertyName, object value) {
		Element elem = null;
		if (value is Element) {
			elem = createElementFromElement(propertyName, (Element) value);
		}
		else if (value is Byte) {
			elem = setAttributes(propertyName, "byte", ((Byte) value).toString());
		}
		else if (value is Short) {
			elem = setAttributes(propertyName, "short", ((Short) value).toString());
		}
		else if (value is Integer) {
			elem = setAttributes(propertyName, "int", ((Integer) value).toString());
		}
		else if (value is Long) {
			elem = setAttributes(propertyName, "long", ((Long) value).toString());
		}
		else if (value is Float) {
			elem = setAttributes(propertyName, "float", ((Float) value).toString());
		}
		else if (value is Double) {
			elem = setAttributes(propertyName, "double", ((Double) value).toString());
		}
		else if (value is Boolean) {
			elem = setAttributes(propertyName, "boolean", ((Boolean) value).toString());
		}
		else if (value is string) {
			elem = createElement(STATE, propertyName);
			elem.setAttribute(ATTRIBUTE_TYPE, "string");
			if (XmlUtilities.hasInvalidXMLCharacters((string) value)) {
				elem.setAttribute("ENCODED_VALUE", NumericUtilities
						.convertBytesToString(((string) value).getBytes(StandardCharsets.UTF_8)));
			}
			else {
				elem.setAttribute(ATTRIBUTE_VALUE, (string) value);
			}
		}
		else if (value is Color) {
			elem = setAttributes(propertyName, "Color", Integer.toString(((Color) value).getRGB()));
		}
		else if (value is Date) {
			elem = setAttributes(propertyName, "Date", DATE_FORMAT.format((Date) value));
		}
		else if (value is File) {
			elem = setAttributes(propertyName, "File", ((File) value).getAbsolutePath());
		}
		else if (value is KeyStroke) {
			elem = setAttributes(propertyName, "KeyStroke", value.toString());
		}
		else if (value is Font font) {
			elem = setAttributes(propertyName, "Font", toFontString(font));
		}
		else if (value is byte[]) {
			elem = createElement("BYTES", propertyName);
			elem.setAttribute(ATTRIBUTE_VALUE,
				NumericUtilities.convertBytesToString((byte[]) value));
		}
		else if (value is short[]) {
			elem = setArrayAttributes(propertyName, "short", value);
		}
		else if (value is int[]) {
			elem = setArrayAttributes(propertyName, "int", value);
		}
		else if (value is long[]) {
			elem = setArrayAttributes(propertyName, "long", value);
		}
		else if (value is float[]) {
			elem = setArrayAttributes(propertyName, "float", value);
		}
		else if (value is double[]) {
			elem = setArrayAttributes(propertyName, "double", value);
		}
		else if (value is bool[]) {
			elem = setArrayAttributes(propertyName, "boolean", value);
		}
		else if (value is string[]) {
			elem = setArrayAttributes(propertyName, "string", value);
		}
		else if (value is Enum) {
			Enum<object> e = (Enum<object>) value;
			elem = createElement("ENUM", propertyName);
			elem.setAttribute(ATTRIBUTE_TYPE, "enum");
			elem.setAttribute("CLASS", e.GetType().getName());
			elem.setAttribute(ATTRIBUTE_VALUE, e.name());
		}
		else if (value is GProperties) {
			Element savedElement = ((GProperties) value).saveToXml();
			elem = createElement(GPROPERTIES_TAG, propertyName);
			elem.setAttribute(ATTRIBUTE_TYPE, G_PROPERTIES_TYPE);
			elem.addContent(savedElement);
		}
		else {
			elem = createElement("NULL", propertyName);
		}
		return elem;
	}

	private Element setArrayAttributes<T>(string propertyName, string type, object values) {
		Element elem = createElement("ARRAY", propertyName);
		elem.setAttribute(ATTRIBUTE_TYPE, type);
		for (int i = 0; i < Array.getLength(values); i++) {
			object value = Array.get(values, i);
			if (value != null) {
				Element arrElem = new Element(ARRAY_ELEMENT_NAME);
				arrElem.setAttribute(ATTRIBUTE_VALUE, value.toString());
				elem.addContent(arrElem);
			}
		}
		return elem;
	}

	protected Element createElement(string tag, string name) {
		Element e = new Element(tag);
		e.setAttribute(ATTRIBUTE_NAME, name);
		initializeElement(e);
		return e;
	}

	protected void initializeElement(Element e) {
		// subclasses may override
	}

	private Element setAttributes(string propertyName, string type, string value) {
		Element elem = createElement(STATE, propertyName);
		elem.setAttribute(ATTRIBUTE_TYPE, type);
		elem.setAttribute(ATTRIBUTE_VALUE, value);
		return elem;
	}

	/**
	 * Save this object to an JsonObject
	 *
	 * @return JsonObject containing the properties
	 */
	public JsonObject saveToJson() {
		JsonObject types = new JsonObject();
		JsonObject values = new JsonObject();
		JsonObject enumClasses = new JsonObject();
		foreach (string key in map.keySet()) {
			object value = map.get(key);
			if (value == null) {
				types.addProperty(key, "null");
				values.addProperty(key, "null");
			}
			else if (value is Element) {
				types.addProperty(key, "xml");
				string outputString = new XMLOutputter().outputString((Element) value);
				values.addProperty(key, outputString);
			}
			else if (value is Color) {
				types.addProperty(key, "Color");
				values.addProperty(key, ((Color) value).getRGB());
			}
			else if (value is Date) {
				types.addProperty(key, "Date");
				values.addProperty(key, DATE_FORMAT.format((Date) value));
			}
			else if (value is File) {
				types.addProperty(key, "File");
				values.addProperty(key, ((File) value).getAbsolutePath());
			}
			else if (value is KeyStroke) {
				types.addProperty(key, "KeyStroke");
				values.addProperty(key, value.toString());
			}
			else if (value is Font font) {
				types.addProperty(key, "Font");
				values.addProperty(key, toFontString(font));
			}
			else if (value is Byte) {
				types.addProperty(key, "byte");
				values.addProperty(key, (Byte) value);
			}
			else if (value is Short) {
				types.addProperty(key, "short");
				values.addProperty(key, (Short) value);
			}
			else if (value is Integer) {
				types.addProperty(key, "int");
				values.addProperty(key, (Integer) value);
			}
			else if (value is Long) {
				types.addProperty(key, "long");
				values.addProperty(key, (Long) value);
			}
			else if (value is Float) {
				types.addProperty(key, "float");
				values.addProperty(key, (Float) value);
			}
			else if (value is Double) {
				types.addProperty(key, "double");
				values.addProperty(key, (Double) value);
			}
			else if (value is Boolean) {
				types.addProperty(key, "boolean");
				values.addProperty(key, (Boolean) value);
			}
			else if (value is string) {
				types.addProperty(key, "String");
				values.addProperty(key, (string) value);
			}
			else if (value is byte[]) {
				JsonArray ja = new JsonArray();
				foreach (byte b in (byte[]) value) {
					ja.add(b);
				}
				types.addProperty(key, "byte[]");
				values.add(key, ja);
			}
			else if (value is short[]) {
				JsonArray ja = new JsonArray();
				foreach (short s in (short[]) value) {
					ja.add(s);
				}
				types.addProperty(key, "short[]");
				values.add(key, ja);
			}
			else if (value is int[]) {
				JsonArray ja = new JsonArray();
				foreach (int i in (int[]) value) {
					ja.add(i);
				}
				types.addProperty(key, "int[]");
				values.add(key, ja);
			}
			else if (value is long[]) {
				JsonArray ja = new JsonArray();
				foreach (long i in (long[]) value) {
					ja.add(i);
				}
				types.addProperty(key, "long[]");
				values.add(key, ja);
			}
			else if (value is float[]) {
				JsonArray ja = new JsonArray();
				foreach (float f in (float[]) value) {
					ja.add(f);
				}
				types.addProperty(key, "float[]");
				values.add(key, ja);
			}
			else if (value is double[]) {
				JsonArray ja = new JsonArray();
				foreach (double f in (double[]) value) {
					ja.add(f);
				}
				types.addProperty(key, "double[]");
				values.add(key, ja);
			}
			else if (value is bool[]) {
				JsonArray ja = new JsonArray();
				foreach (bool b in (bool[]) value) {
					ja.add(b);
				}
				types.addProperty(key, "boolean[]");
				values.add(key, ja);
			}
			else if (value is string[]) {
				JsonArray ja = new JsonArray();
				foreach (string s in (string[]) value) {
					if (s != null) {
						ja.add(s);
					}
				}
				types.addProperty(key, "String[]");
				values.add(key, ja);
			}
			else if (value is Enum) {
				Enum<object> e = (Enum<object>) value;
				types.addProperty(key, "enum");
				enumClasses.addProperty(key, e.GetType().getName());
				values.addProperty(key, e.name());
			}
			else if (value is GProperties) {
				types.addProperty(key, G_PROPERTIES_TYPE);
				JsonObject json = ((GProperties) value).saveToJson();
				values.add(key, json);
			}
			else {
				throw new AssertException("found unsupported object type: " + value.GetType());
			}
		}
		JsonObject jsonObject = new JsonObject();
		jsonObject.addProperty(PROPERTIES_NAME, propertiesName);
		jsonObject.add("VALUES", values);
		jsonObject.add("TYPES", types);
		jsonObject.add("ENUM_CLASSES", enumClasses);
		return jsonObject;
	}

	protected Element createElementFromElement(string internalKey, Element internalElement) {
		Element newElement = createElement("XML", internalKey);

		Element internalElementClone = internalElement.clone();
		newElement.addContent(internalElementClone);

		return newElement;
	}

