	protected T getAsType<T>(string name, T defaultValue, Class<T> clazz) {
		if (map.containsKey(name)) {
			object value = map.get(name);
			if (isExpectedType(name, value, clazz)) {
				return clazz.cast(value);
			}
		}
		return defaultValue;

	}

	private bool isExpectedType(string name, object value, Class<object> expectedType) {
		if (value != null && !expectedType.isInstance(value)) {
			Msg.debug(this,
				"Type mismatch on GProperties property \"" + name +
					"\". Attempted to retrieve value as a " + expectedType.getName() +
					" but was of type " + value.GetType().getName());
			return false;
		}
		return true;
	}

	private static string toFontString(Font font) {
		return string.format("%s-%s-%s", font.getName(), getStyleString(font), font.getSize());
	}

	private static string getStyleString(Font font) {
		bool bold = font.isBold();
		bool italic = font.isItalic();
		if (bold && italic) {
			return "BOLDITALIC";
		}
		if (bold) {
			return "BOLD";
		}
		if (italic) {
			return "ITALIC";
		}
		return "PLAIN";
	}

}
